// Preferred: Runnable + ExecutorService
Runnable task = () -> System.out.println("Running");
ExecutorService exec = Executors.newFixedThreadPool(4);
exec.submit(task);
exec.shutdown();

class Counter {
  private int count = 0;
  public synchronized void increment() { count++; }
  public synchronized int get() { return count; }
}

// Or block-level:
synchronized(lock) {
  // only one thread at a time
}

// volatile for a stop flag — correct
private volatile boolean running = true;
void run() { while(running) { doWork(); } }
void stop() { running = false; } // visible immediately

// volatile for counter — WRONG (i++ not atomic)
private volatile int count = 0;
void inc() { count++; } // race condition!

ReentrantLock lock = new ReentrantLock();
lock.lock();
try {
  // critical section
} finally {
  lock.unlock(); // always in finally
}

// Try with timeout:
if (lock.tryLock(500, TimeUnit.MILLISECONDS)) {
  try { /* work */ } finally { lock.unlock(); }
}

ThreadLocal<SimpleDateFormat> formatter =
  ThreadLocal.withInitial(() -> new SimpleDateFormat("yyyy-MM-dd"));

// In each thread:
String today = formatter.get().format(new Date());
formatter.remove(); // cleanup in thread pool!

StampedLock lock = new StampedLock();
long stamp = lock.tryOptimisticRead();
double x = this.x, y = this.y; // read without lock
if (!lock.validate(stamp)) {
  stamp = lock.readLock();
  try { x = this.x; y = this.y; }
  finally { lock.unlockRead(stamp); }
}
